package fitnessrules

import "testing"

// A file server over the data directory built on Go 1.24's os.Root is the
// same exposure as http.FileServer(http.Dir(dataDir)): report bytes served
// under the site policy. The byte-path rule must trip on it.
func TestByteRuleCatchesOpenRootFileServer(t *testing.T) {
	rules := loadRules(t, repoRoot(t))
	r, ok := rules["report bytes are written only by serveRaw"]
	if !ok {
		t.Fatal("the byte-path rule is not in fitness.yaml")
	}
	for _, text := range []string{
		"root, err := os.OpenRoot(cfg.DataDir)\nif err != nil {\n\treturn err\n}\nmux.Handle(\"GET /data/\", http.FileServerFS(root.FS()))",
		"mux.Handle(\"GET /files/\", http.StripPrefix(\"/files/\", http.FileServerFS(mustRoot(dataDir).FS())))\n\nfunc mustRoot(d string) *os.Root { r, _ := os.OpenRoot(d); return r }",
	} {
		if fired, _ := r.fires("cmd/hband/main.go", text); !fired {
			t.Errorf("the byte-path rule is quiet on a file server over a directory opened with os.OpenRoot:\n%s", text)
		}
	}
}

package fitnessrules

import "testing"

// Go code that writes a frame, or a forbidden sandbox token, in the middle of
// a string (not at its start, where the string-literal rule looks) is still a
// site page framing a report: some architecture rule must trip on it.
func TestRulesSeeFrameMarkupInsideGoStrings(t *testing.T) {
	rules := loadRules(t, repoRoot(t))
	for _, text := range []string{
		`fmt.Fprintf(w, "Report: %s <iframe src=/raw/%s></iframe>", title, slug)`,
		`fmt.Fprintf(w, "%s<iframe sandbox='allow-scripts' src=/raw/%s></iframe>", title, slug)`,
	} {
		fired := false
		for _, r := range rules {
			if got, _ := r.fires("internal/server/reader.go", text); got {
				fired = true
			}
		}
		if !fired {
			t.Errorf("no rule trips on a Go handler that writes a frame mid-string: %s", text)
		}
	}
}

package fitnessrules

import "testing"

// A file server over the data directory opened with os.OpenRoot (Go 1.24+)
// serves report bytes under the site policy, exactly like
// http.FileServer(http.Dir(dataDir)): some architecture rule must trip on it.
func TestRulesSeeFileServerOverOpenRoot(t *testing.T) {
	rules := loadRules(t, repoRoot(t))
	for _, c := range []struct{ path, text string }{
		{"internal/server/reader.go", `root, _ := os.OpenRoot(a.cfg.DataDir); mux.Handle("GET /files/", http.FileServerFS(root.FS()))`},
		{"cmd/hband/main.go", `dataRoot, _ := os.OpenRoot(cfg.DataDir); h := http.FileServerFS(dataRoot.FS())`},
	} {
		fired := false
		for _, r := range rules {
			if got, _ := r.fires(c.path, c.text); got {
				fired = true
			}
		}
		if !fired {
			t.Errorf("no rule trips at %s on: %s", c.path, c.text)
		}
	}
}
